        question: '什么是社会保障卡？有些什么功能？',
        answer: `社会保障卡全称为“中华人民共和国社会保障卡”，简称“社保卡”，社会保障卡是人社部门联合商业银行面向社会公众发行的集成电路卡，是持卡人享受人力资源和社会保障权益及政府其他公共服务权益的电子凭证。具有身份凭证、信息记录、信息查询、就医结算、缴费和待遇等社会保障应用基本功能（简称“社保功能”），以及现金存取、转账支付等金融应用功能（简称“金融功能”）。

内江市社会保障卡服务管理部门为内江市人力资源社会保障数据网络中心，联系电话为0832-2177999。`
