        question: '城乡居民基本养老保险的参保范围是哪些人？',
        answer: `城乡居民基本养老保险的参保范围是指：年满16周岁（不含在校学生），非国家机关和事业单位工作人员及不属于职工基本养老保险制度覆盖范围的城乡居民，可以在户籍地参加城乡居民养老保险。`
