        question: '怎样缴纳城乡居民基本养老保险费最划算？',
        answer: `①符合条件早参保。积累更多缴费年限（正常缴费年限超过15年的，每超过1年，基础养老金每月增加2元）。

②按年缴费不断保。按年能获得政府缴费补贴（政府补贴只对当年缴当年保费的实施补贴，对中断补缴等不给予补贴）。

③选择较高档次缴费。政府补贴多；个人账户积累多；养老金待遇高。

简单说即：早参保、不断保、多缴费、待遇高。`
