公式说明：1.发放月数计算：缴费年限满15年死亡的，对应为9个月，缴费年限每增加1年对应增加1个月，24个月封顶；已领取待遇死亡的，每领取1年减少1个月，最低为9个月；其余情况参照《企业职工基本养老保险遗属待遇暂行办法》（人社部发﹝2021﹞18号）计算。

