        question: '哪些工伤保险待遇应从工伤保险基金中支付？哪些由用人单位支付？',
        answer: `因工伤发生的下列费用，按照国家规定从工伤保险基金中支付：

（一）治疗工伤的医疗费用和康复费用；

（二）住院伙食补助费；

（三）到统筹地区以外就医的交通食宿费；

（四）安装配置伤残辅助器具所需费用；

（五）生活不能自理的，经劳动能力鉴定委员会确认的生活护理费；

（六）一次性伤残补助金和一至四级伤残职工按月领取的伤残津贴；

（七）终止或者解除劳动合同时，应当享受的一次性医疗补助金；

（八）因工死亡的，其遗属领取的丧葬补助金、供养亲属抚恤金因工死亡补助金；

（九）劳动能力鉴定费。

因工伤发生的下列费用，按照国家规定由用人单位支付：

（一）治疗工伤期间的工资福利；

（二）五级、六级伤残职工按月领取的伤残津贴；

（三）终止或者解除劳动合同时，应当享受的一次性伤残就业补助金。`
