        answer: `《工伤保险条例》第三十三条第三款生活不能自理的工伤职工在停工留薪期需要护理的，由所在单位负责。

工人受工伤住院的，如果医院出具需要日常生活护理的证明，那么用人单位应该派专人负责受伤工人的护理工作。在现实当中，职工发生工伤后，许多单位都把护理的责任推给职工本人，又不支付任何护理费，这种情况下，职工可以自己先雇佣护理工，并保存雇工费用票据，最后由单位来支付这笔费用。`
