        question: '灵活就业人员参加职工医保如何参保缴费？',
        answer: `灵活就业人员新参加职工医保的，应到户籍所在地医保经办机构办理职工医保参保登记；本市居住的外地户籍居民到居住地医保经办机构办理职工医保参保登记。也可以通过国家医保服务平台APP地方专区、四川医保APP以及四川医保公共服务平台微信、支付宝小程序等申请办理参保登记。参续保人员均可在税务部门缴费平台、税务部门指定的代收代缴银行和第三方平台进行缴费或协议代扣。因代扣协议信息无效或银行账户余额不足无法扣款，影响医疗保险待遇享受的，由参保人员自行承担。`
