        question: '灵活就业人员多缴纳了医保费怎么办？',
        answer: `灵活就业人员因就业原因随用人单位参保，可凭相关资料向医保经办机构申请退还以灵活就业人员身份参加职工医保的重复缴费部分费用，退费金额以办理退费手续的次月起计算。灵活就业人员达到法定退休年龄且已达到最低缴费年限，未及时办理退休清算，仍在继续缴纳职工医保费的，超出缴费年限可从已达到医保最低缴费年限的次月起退还，已享受职工医保待遇的从享受待遇的次月起退还。`
