        answer: `生育保险连续缴费6个月以上且符合生育政策的职工医保参保人员，可享受生育医疗费（含产前检查费1000元），生育医疗费待遇享受以出院时间为准。生育医疗费实行限额结算，结算标准为：顺产5000元、剖宫产6000元；多胞胎每多产一孩增加1000元。

生育保险连续缴费12个月以上的，且符合生育政策的可享受生育津贴。生育津贴计算公式为：职工所在用人单位上年度职工月平均工资（元）×12（月）÷365（天）×产假天数。`
