        answer: `住院和门诊慢特病救助共用年度救助限额，对特困人员、孤儿按100%的比例救助，年度救助限额为9000元；对低保对象按70％的比例救助，年度救助限额为7000元；对防止返贫监测对象按65％的比例救助，年度救助限额为7000元；对低保边缘家庭成员、因病致贫重病患者按50％的比例救助，年度救助限额为5000元。

门诊慢特病和住院医疗费用合并计算起付标准。对特困人员、孤儿、低保对象不设起付标准，防止返贫监测对象、低保边缘家庭成员、因病致贫重病患者的起付标准分别按我市上年度城乡居民人均可支配收入的5%、10％、25％确定（2025年为1637元、3273元、8183元）。`
