        answer: `1.领卡办理时间：每年招生工作期间（具体办理时间以当年教育部门正式发布的通知为准）。办理流程：申请人到居住地辖区教育行政部门指定地点提交进城务工人员相关材料→审查组当场初审材料→初审通过后，申请人领取学位申请卡→申请人须认真填写学位申请卡上相关内容，尤其要理性填报申请就读学校。

2.返卡办理时间：（具体办理时间以当年教育部门正式发布的通知为准）。办理流程：申请人将填好的学位申请卡交回办理点→审查组复查，通过后签字、盖章→学位申请副卡交申请人保管，主卡由辖区教育行政部门统一管理。复核未通过的，取消主城区学位申请资格。`
