（二）线上申请流程。

方式一：网页端申请登录四川政务服务网→实名注册后再次登录→选择“一件事服务”→选择“申请公租房一件事”→选择“内江市”→选择“立即申请”，进入四川省住房保障管理服务平台进行申报。

